import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9

    def read_records(text):
        stream = io.StringIO(text, newline="")
        reader = csv.reader(
            stream,
            delimiter=",",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False,
        )
        records = []
        try:
            for record in reader:
                if record and any(value != "" for value in record):
                    records.append([str(value) for value in record])
        except csv.Error:
            return []
        return records

    def header_score(record, following):
        if len(record) != expected_width:
            return -1
        score = 0
        nonempty = sum(bool(value.strip()) for value in record)
        score += nonempty * 4
        if nonempty == expected_width:
            score += 20

        normalized = []
        for value in record:
            value = value.strip()
            token = re.sub(r"[\s_\-]+", "", value)
            normalized.append(token.lower())
            if re.search(r"[A-Za-z]", value):
                score += 2
            if token and re.fullmatch(r"[A-Za-z][A-Za-z0-9]*", token):
                score += 3
            if re.search(r"://", value):
                score -= 12
            if re.search(r"\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}", value):
                score -= 10
            if re.fullmatch(r"[-+]?\d+(?:\.\d+)?", value):
                score -= 8

        if len(set(normalized)) == expected_width:
            score += 5
        score += sum(1 for row in following[:5] if len(row) == expected_width) * 3
        return score

    records = read_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    candidates = []
    search_limit = min(len(records), 100)
    for index in range(search_limit):
        score = header_score(records[index], records[index + 1:index + 6])
        if score >= 0:
            candidates.append((score, -index, index))

    if not candidates:
        columns = list(records[0])
        if columns:
            columns[0] = columns[0].lstrip("\ufeff")
        width = len(columns)
        rows = []
        for row in records[1:]:
            if len(row) < width:
                row = row + [""] * (width - len(row))
            elif len(row) > width and width:
                row = row[:width - 1] + [",".join(row[width - 1:])]
            rows.append(row)
        return {"columns": columns, "rows": rows}

    header_index = max(candidates)[2]
    columns = list(records[header_index])
    columns[0] = columns[0].lstrip("\ufeff")
    data = [list(row) for row in records[header_index + 1:]]

    def is_date_like(value):
        value = value.strip()
        patterns = (
            r"\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}",
            r"\d{4}-\d{1,2}-\d{1,2}(?:[T ]\d{1,2}:\d{2}(?::\d{2})?)?",
        )
        return any(re.fullmatch(pattern, value) for pattern in patterns)

    representative = [row for row in data[:30] if row]
    date_count = sum(is_date_like(row[0]) for row in representative)
    date_dominant = bool(representative) and date_count >= max(2, len(representative) // 2)

    if date_dominant:
        while data:
            row = data[-1]
            if len(row) == expected_width or (row and is_date_like(row[0])):
                break
            if len(row) <= 2 and all(
                not re.search(r"\d{1,4}[/.-]\d{1,2}[/.-]\d{1,4}", value)
                for value in row
            ):
                data.pop()
            else:
                break

    normalized_headers = [
        re.sub(r"[^a-z0-9]+", "", value.lower()) for value in columns
    ]
    url_index = next(
        (i for i, value in enumerate(normalized_headers) if "url" in value or "link" in value),
        None,
    )
    description_index = next(
        (
            i
            for i, value in enumerate(normalized_headers)
            if "description" in value or "details" in value
        ),
        None,
    )

    def normalize_row(row):
        row = list(row)
        if len(row) == expected_width:
            return row
        if len(row) < expected_width:
            return row + [""] * (expected_width - len(row))

        if (
            url_index is not None
            and description_index is not None
            and description_index < url_index
        ):
            source_url = next(
                (
                    i
                    for i, value in enumerate(row)
                    if re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", value.strip())
                ),
                None,
            )
            if source_url is not None and source_url >= url_index:
                prefix = row[:description_index]
                description = ",".join(row[description_index:source_url])
                rebuilt = prefix + [description]

                while len(rebuilt) < url_index:
                    rebuilt.append("")
                rebuilt.append(row[source_url])

                suffix = row[source_url + 1:]
                remaining = expected_width - len(rebuilt)
                if remaining > 0:
                    if len(suffix) <= remaining:
                        rebuilt.extend(suffix)
                        rebuilt.extend([""] * (expected_width - len(rebuilt)))
                    else:
                        rebuilt.extend(suffix[:remaining - 1])
                        rebuilt.append(",".join(suffix[remaining - 1:]))
                if len(rebuilt) == expected_width:
                    return rebuilt

        return row[:expected_width - 1] + [",".join(row[expected_width - 1:])]

    rows = [normalize_row(row) for row in data]
    return {"columns": columns, "rows": rows}
